</script>
<style>
:root {
  --primary: #FF9800;
  --primary-dark: #e68900;
  --primary-light: #fff3e0;
  --border-light: #f0ece1;
  --bg: #ffffff;
  --bg-alt: #f7f7f7;
  --text: #1a1a1a;
  --text-muted: #666;
  --border: #e0e0e0;
  --card-shadow: 0 2px 12px rgba(0,0,0,.08);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.7;display:flex;flex-direction:column;min-height:100vh}
a{color:var(--primary);text-decoration:none}a:hover{text-decoration:underline}img{max-width:100%;height:auto;display:block}
.site-header{
  background:rgba(255,255,255,.92);
  backdrop-filter:blur(16px) saturate(1.2);
  border-bottom:3px solid var(--primary);
  padding:0 1rem;
  position:sticky;
  top:0;
  z-index:1000;
}
.nav-wrap{
  max-width:1200px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  height:72px;
}
.logo{
  font-size:1.4rem;
  font-weight:900;
  letter-spacing:-1px;
  background:linear-gradient(135deg,var(--primary-dark),var(--primary));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
  flex-shrink:0;
}
.logo span{font-weight:400;color:var(--text-muted);-webkit-text-fill-color:var(--text-muted);}
.logo:hover{text-decoration:none}
.main-nav{display:flex;align-items:center}
.nav-links{display:flex;gap:0;list-style:none;align-items:center;margin:0;padding:0}
.nav-links > li{position:relative}
.nav-links > li > a{
  color:var(--text);
  font-weight:600;
  font-size:.85rem;
  padding:.4rem 1rem;
  border-radius:50px;
  transition:.2s;
  letter-spacing:.2px;
  display:flex;
  align-items:center;
  gap:.3rem;
  white-space:nowrap;
}
.nav-links > li > a .arrow{
  font-size:.6rem;
  transition:transform .25s;
  display:inline-block;
}
.nav-links > li:hover > a .arrow{
  transform:rotate(180deg);
}
.nav-links > li > a:hover,
.nav-links > li > a.active{
  color:#fff;
  background:var(--primary);
  text-decoration:none;
}
.nav-links > li.simple-link > a{
  color:var(--text-muted);
  font-weight:500;
  font-size:.8rem;
}
.nav-links > li.simple-link > a:hover{
  color:#fff;
}
.mega-panel{
  position:absolute;
  top:100%;
  left:50%;
  transform:translateX(-50%) translateY(12px);
  background:#fff;
  border-radius:16px;
  box-shadow:0 20px 60px rgba(0,0,0,.15), 0 4px 20px rgba(0,0,0,.06);
  min-width:680px;
  max-width:900px;
  padding:0;
  opacity:0;
  visibility:hidden;
  transition:all .25s cubic-bezier(.16,1,.3,1);
  border:1px solid var(--border-light);
  overflow:hidden;
  pointer-events:none;
}
.nav-links > li:hover .mega-panel{
  opacity:1;
  visibility:visible;
  transform:translateX(-50%) translateY(8px);
  pointer-events:auto;
}
.mega-grid{
  display:grid;
  gap:0;
  padding:1.5rem;
}
.mega-grid.cols-2{grid-template-columns:1fr 1fr}
.mega-grid.cols-3{grid-template-columns:1fr 1fr 1fr}
.mega-grid.cols-4{grid-template-columns:1fr 1fr 1fr 1fr}
.mega-col{
  padding:0 .8rem;
  border-right:1px solid var(--border-light);
}
.mega-col:last-child{border-right:none}
.mega-col h4{
  font-size:.7rem;
  text-transform:uppercase;
